package com.hellodoc.exception;
import com.hellodoc.dto.ApiError; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.format.DateTimeParseException; import java.util.*;
@RestControllerAdvice
public class ApiExceptionHandler {
 private static final Logger log=LoggerFactory.getLogger(ApiExceptionHandler.class);
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(ApiError.of(400,"VALIDATION_ERROR","Certaines données sont invalides.",fields));}
 @ExceptionHandler(ResponseStatusException.class) ResponseEntity<ApiError> status(ResponseStatusException e){int s=e.getStatusCode().value();String message=e.getReason()==null?"La requête n’a pas pu être traitée.":e.getReason();return ResponseEntity.status(s).body(ApiError.of(s,s==404?"NOT_FOUND":s==409?"CONFLICT":s==403?"FORBIDDEN":"REQUEST_ERROR",message,Map.of()));}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ApiError> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(ApiError.of(400,"VALIDATION_ERROR",e.getMessage(),Map.of()));}
 @ExceptionHandler({MethodArgumentTypeMismatchException.class,HttpMessageNotReadableException.class,DateTimeParseException.class}) ResponseEntity<ApiError> malformed(Exception e){return ResponseEntity.badRequest().body(ApiError.of(400,"MALFORMED_REQUEST","La requête contient une valeur ou un format invalide.",Map.of()));}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ApiError> conflict(DataIntegrityViolationException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(ApiError.of(409,"CONFLICT","L’opération entre en conflit avec des données enregistrées. Actualisez puis réessayez.",Map.of()));}
 @ExceptionHandler(Exception.class) ResponseEntity<ApiError> unexpected(Exception e){log.error("Unexpected API error",e);return ResponseEntity.internalServerError().body(ApiError.of(500,"INTERNAL_ERROR","Une erreur interne est survenue.",Map.of()));}
}
